/**
 * Reads an uploaded or stored video file frame by frame (upload assessment, eval harness). Frames are drawn into a
 * canvas on demand; nothing is kept or sent anywhere.
 */

export interface OpenedVideo {
  video: HTMLVideoElement;
  bytes: number;
  duration: number;
  close(): void;
}

export async function openVideo(src: Blob | string): Promise<OpenedVideo> {
  const blob = typeof src === 'string' ? await (await fetch(src)).blob() : src;
  const url = URL.createObjectURL(blob);
  const v = document.createElement('video');
  v.muted = true;
  v.playsInline = true;
  v.preload = 'auto';
  v.src = url;
  try {
    await new Promise<void>((res, rej) => {
      v.onloadeddata = () => res();
      v.onerror = () => rej(new Error('video decode'));
    });
  } catch (e) {
    URL.revokeObjectURL(url);
    throw e;
  }
  return {
    video: v,
    bytes: blob.size,
    duration: v.duration,
    close: () => {
      v.removeAttribute('src');
      v.load();
      URL.revokeObjectURL(url);
    },
  };
}

export function seekVideo(v: HTMLVideoElement, t: number): Promise<void> {
  return new Promise((res) => {
    if (Math.abs(v.currentTime - t) < 1e-3 && v.readyState >= 2) {
      res();
      return;
    }
    const on = () => {
      v.removeEventListener('seeked', on);
      res();
    };
    v.addEventListener('seeked', on);
    v.currentTime = t;
  });
}

/** The current frame, long edge at most `maxEdge` px. */
export function grabVideoFrame(v: HTMLVideoElement, maxEdge = 1280): HTMLCanvasElement {
  const s = Math.min(1, maxEdge / Math.max(v.videoWidth, v.videoHeight));
  const c = document.createElement('canvas');
  c.width = Math.round(v.videoWidth * s);
  c.height = Math.round(v.videoHeight * s);
  c.getContext('2d')!.drawImage(v, 0, 0, c.width, c.height);
  return c;
}
