/**
 * When a photo was taken: EXIF DateTimeOriginal (or DateTime) of a JPEG, read from the first 128 KB without a
 * library. Used to date uploaded photos so older pictures land at the right day of the recovery curve.
 * Returns null for other formats or when the tag is missing (the caller falls back to the file date).
 */
export function exifDateFromBytes(buf: ArrayBuffer): Date | null {
  const d = new DataView(buf);
  if (d.byteLength < 4 || d.getUint16(0) !== 0xffd8) return null;
  let p = 2;
  while (p + 4 <= d.byteLength) {
    const marker = d.getUint16(p);
    const len = d.getUint16(p + 2);
    if ((marker & 0xff00) !== 0xff00 || len < 2) return null;
    // APP1 "Exif\0\0"
    if (marker === 0xffe1 && p + 10 <= d.byteLength && d.getUint32(p + 4) === 0x45786966 && d.getUint16(p + 8) === 0) {
      return tiffDate(d, p + 10, Math.min(d.byteLength, p + 2 + len));
    }
    if (marker === 0xffda) return null; // image data starts: no EXIF
    p += 2 + len;
  }
  return null;
}

function tiffDate(d: DataView, t: number, end: number): Date | null {
  if (t + 8 > end) return null;
  const le = d.getUint16(t) === 0x4949;
  const u16 = (o: number) => d.getUint16(t + o, le);
  const u32 = (o: number) => d.getUint32(t + o, le);
  const ascii = (o: number, n: number) => {
    let s = '';
    for (let i = 0; i < n && t + o + i < end; i++) {
      const c = d.getUint8(t + o + i);
      if (c === 0) break;
      s += String.fromCharCode(c);
    }
    return s;
  };
  const readIfd = (off: number): Map<number, { type: number; count: number; value: number }> => {
    const m = new Map<number, { type: number; count: number; value: number }>();
    if (t + off + 2 > end) return m;
    const n = u16(off);
    for (let i = 0; i < n; i++) {
      const e = off + 2 + 12 * i;
      if (t + e + 12 > end) break;
      m.set(u16(e), { type: u16(e + 2), count: u32(e + 4), value: u32(e + 8) });
    }
    return m;
  };
  const ifd0 = readIfd(u32(4));
  const exifPtr = ifd0.get(0x8769);
  const exif = exifPtr ? readIfd(exifPtr.value) : new Map();
  const tag = exif.get(0x9003) ?? exif.get(0x9004) ?? ifd0.get(0x0132);
  if (!tag || tag.type !== 2 || tag.count < 19) return null;
  const m = ascii(tag.value, 19).match(/^(\d{4}):(\d{2}):(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (!m) return null;
  const date = new Date(+m[1]!, +m[2]! - 1, +m[3]!, +m[4]!, +m[5]!, +m[6]!);
  return Number.isNaN(date.getTime()) ? null : date;
}

/** Capture date of an uploaded file: EXIF for JPEG, else the file's modification time. */
export async function captureDate(file: File): Promise<{ date: Date; source: 'exif' | 'file' }> {
  if (/jpe?g$/i.test(file.type) || /\.jpe?g$/i.test(file.name)) {
    const exif = exifDateFromBytes(await file.slice(0, 128 * 1024).arrayBuffer());
    if (exif) return { date: exif, source: 'exif' };
  }
  return { date: new Date(file.lastModified || Date.now()), source: 'file' };
}
